<script setup lang="ts">
import {computed,ref} from 'vue';
import {type Handoff,type HandoffDraft,type ResultType,handoffChanged,permittedActions} from './handoff-contract';
import {handoffCopy,handoffEventLabel} from './handoff-i18n';
import HandoffFacts from './HandoffFacts.vue';
const p=defineProps<{handoff:Handoff;draft:HandoffDraft;lang:'zh'|'en';identity:string;role:string;disabled:boolean;pending:boolean}>();
const emit=defineEmits<{select:[id:string,type:ResultType];patch:[value:Partial<HandoffDraft>];submit:[];cancel:[];rebind:[];refresh:[id:string];background:[id:string]}>();
const t=computed(()=>handoffCopy[p.lang]),active=computed(()=>p.draft.target?.id===p.handoff.id),changed=computed(()=>active.value&&handoffChanged(p.draft,p.handoff)),actions=computed(()=>permittedActions(p.handoff,p.identity,p.role));
const composing=ref(false),label=(type:string)=>handoffEventLabel(type,p.lang);
function input(e:Event,key:'text'|'reason'){emit('patch',{[key]:(e.target as HTMLTextAreaElement).value,confirmed:false,scopeReviewed:false});}
</script>
<template><section class="handoff-result-editor" :data-handoff-id="handoff.id"><h3>{{t.title}}</h3><HandoffFacts :handoff="handoff" :lang="lang" history/><p v-if="handoff.status==='ACCEPTED'&&handoff.acceptanceEvidence!=='verified'" role="alert">{{t.unverified}}</p><div class="button-row"><button type="button" :id="'handoff-background-'+handoff.id" :disabled="disabled" @click="emit('background',handoff.id)">{{t.background}}</button><button type="button" :disabled="disabled" @click="emit('refresh',handoff.id)">{{t.refresh}}</button></div><div v-if="!active" class="button-row"><button v-for="a in actions" :key="a" type="button" :data-result-action="a" :disabled="disabled" @click="emit('select',handoff.id,a)">{{label(a)}}</button></div><form v-else class="handoff-result-form" @submit.prevent="emit('submit')" @compositionstart="composing=true" @compositionend="composing=false"><fieldset :disabled="disabled"><h4>{{t.edit}}</h4><p class="handoff-draft-state" role="status">{{pending?t.pending:t.draft}}</p><div v-if="changed" class="handoff-result-conflict alert warning"><h4>{{t.conflict}}</h4><h5>{{t.bound}}</h5><HandoffFacts :handoff="draft.target!" :lang="lang"/><h5>{{t.latest}}</h5><HandoffFacts :handoff="handoff" :lang="lang"/><h5>{{t.input}}</h5><p class="preserve-text">{{draft.text}}</p><p class="preserve-text">{{draft.reason}}</p><label class="check-label"><input id="handoff-scope-reviewed" type="checkbox" :checked="draft.scopeReviewed" @change="emit('patch',{scopeReviewed:($event.target as HTMLInputElement).checked})">{{t.compare}}</label><button id="handoff-rebind" type="button" :disabled="!draft.scopeReviewed" @click="emit('rebind')">{{t.rebind}}</button></div><label for="handoff-event-type">{{t.select}}<select id="handoff-event-type" :value="draft.type" @change="emit('patch',{type:($event.target as HTMLSelectElement).value as ResultType,confirmed:false,scopeReviewed:false})"><option v-if="!actions.includes(draft.type)" :value="draft.type" disabled>{{label(draft.type)}}</option><option v-for="a in actions" :key="a" :value="a">{{label(a)}}</option></select></label><p v-if="!actions.includes(draft.type)" role="alert">{{t.notAllowed}}</p><label v-if="['result-recorded','result-corrected','correction-requested'].includes(draft.type)" for="handoff-result-text">{{t.text}}<textarea id="handoff-result-text" :value="draft.text" rows="4" maxlength="4000" required @input="input($event,'text')"></textarea></label><label v-if="['result-corrected','completion-withdrawn'].includes(draft.type)" for="handoff-result-reason">{{t.reason}}<textarea id="handoff-result-reason" :value="draft.reason" rows="3" maxlength="1000" required @input="input($event,'reason')"></textarea></label><template v-if="draft.type==='completed'"><p class="preserve-text">{{draft.target?.result.latestResult?.text}}</p><label class="check-label"><input id="handoff-complete-confirm" type="checkbox" :checked="draft.confirmed" @change="emit('patch',{confirmed:($event.target as HTMLInputElement).checked})">{{t.confirm}}</label></template><p v-if="draft.type==='completion-withdrawn'">{{t.withdrawHint}}</p><div class="button-row"><button id="handoff-submit" type="submit" :disabled="changed||composing||!actions.includes(draft.type)||draft.type==='completed'&&!draft.confirmed">{{t.save}}</button><button id="handoff-cancel" type="button" @click="emit('cancel')">{{t.cancel}}</button></div></fieldset></form></section></template>
